{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.Planned_putaway_identifier AS WITH base AS ( SELECT UPPER(TRIM(cleaned_sku)) AS sku_group, CASE WHEN remarks_final ILIKE \'JAN%\' THEN 1 WHEN remarks_final ILIKE \'FEB%\' THEN 2 WHEN remarks_final ILIKE \'MAR%\' THEN 3 WHEN remarks_final ILIKE \'APR%\' THEN 4 WHEN remarks_final ILIKE \'MAY%\' THEN 5 WHEN remarks_final ILIKE \'JUN%\' THEN 6 WHEN remarks_final ILIKE \'JUL%\' THEN 7 WHEN remarks_final ILIKE \'AUG%\' THEN 8 WHEN remarks_final ILIKE \'SEP%\' THEN 9 WHEN remarks_final ILIKE \'OCT%\' THEN 10 WHEN remarks_final ILIKE \'NOV%\' THEN 11 WHEN remarks_final ILIKE \'DEC%\' THEN 12 ELSE NULL END AS planned_month FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks ), planned_skus AS ( SELECT DISTINCT sku_group FROM base WHERE sku_group IS NOT NULL AND planned_month > 4 ), base_unique AS ( SELECT sku_group, planned_month FROM base WHERE sku_group IS NOT NULL AND planned_month > 4 QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group, planned_month ORDER BY sku_group ) = 1 ), inward AS ( SELECT UPPER( TRIM( REGEXP_REPLACE( \"Item Type skuCode\", \'-[0-9A-Za-z]{1,5}$\', \'\' ) ) ) AS sku_group, MONTH(putaway_completed_date) AS inward_month, SUM( TRY_TO_NUMBER(putaway_completed_quantity) ) AS inwarded_qty FROM snitch_db.maplemonk.putaway_tracking WHERE final_type ILIKE \'New inward\' AND is_trading ILIKE \'True\' AND MONTH(putaway_completed_date) >4 AND YEAR(putaway_completed_date) = 2026 GROUP BY 1, 2 HAVING SUM( TRY_TO_NUMBER(putaway_completed_quantity) ) > 100 ), planned_counts AS ( SELECT sku_group, COUNT(*) AS planned_count, MAX(planned_month) AS max_planned_month FROM base_unique GROUP BY 1 ), inward_counts AS ( SELECT sku_group, COUNT(*) AS inward_count FROM inward GROUP BY 1 ), sku_counts AS ( SELECT p.sku_group, p.planned_count, COALESCE(i.inward_count, 0) AS inward_count, p.max_planned_month, GREATEST( COALESCE(i.inward_count, 0) - p.planned_count, 0 ) AS extra_planned_rows FROM planned_counts p LEFT JOIN inward_counts i ON p.sku_group = i.sku_group ), planned_original AS ( SELECT sku_group, planned_month, \'ORIGINAL\' AS row_type, 0 AS duplicate_no FROM base_unique ), planned_duplicates AS ( SELECT c.sku_group, c.max_planned_month AS planned_month, \'DUPLICATE\' AS row_type, f.index + 1 AS duplicate_no FROM sku_counts c, LATERAL FLATTEN( INPUT => ARRAY_GENERATE_RANGE( 0, c.extra_planned_rows ) ) f WHERE c.extra_planned_rows > 0 ), planned_expanded AS ( SELECT sku_group, planned_month, row_type, duplicate_no FROM planned_original UNION ALL SELECT sku_group, planned_month, row_type, duplicate_no FROM planned_duplicates ), planned_ranked AS ( SELECT sku_group, planned_month, row_type, duplicate_no, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY planned_month DESC, CASE WHEN row_type = \'ORIGINAL\' THEN 1 ELSE 2 END, duplicate_no ) AS planned_rn FROM planned_expanded ), inward_ranked AS ( SELECT sku_group, inward_month, inwarded_qty, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY inward_month DESC ) AS inward_rn FROM inward ), planned_inward AS ( SELECT p.sku_group, p.planned_month, i.inward_month, i.inwarded_qty, \'PLANNED\' AS status FROM planned_ranked p INNER JOIN inward_ranked i ON p.sku_group = i.sku_group AND p.planned_month <= i.inward_month ), unplanned_inward AS ( SELECT i.sku_group, NULL AS planned_month, i.inward_month, i.inwarded_qty, \'UNPLANNED\' AS status FROM inward i LEFT JOIN planned_skus p ON i.sku_group = p.sku_group WHERE p.sku_group IS NULL ), final AS ( SELECT sku_group, planned_month, inward_month, inwarded_qty, status FROM planned_inward UNION ALL SELECT sku_group, planned_month, inward_month, inwarded_qty, status FROM unplanned_inward ) SELECT sku_group, planned_month, CASE WHEN planned_month = 1 THEN \'JANUARY\' WHEN planned_month = 2 THEN \'FEBRUARY\' WHEN planned_month = 3 THEN \'MARCH\' WHEN planned_month = 4 THEN \'APRIL\' WHEN planned_month = 5 THEN \'MAY\' WHEN planned_month = 6 THEN \'JUNE\' WHEN planned_month = 7 THEN \'JULY\' WHEN planned_month = 8 THEN \'AUGUST\' WHEN planned_month = 9 THEN \'SEPTEMBER\' WHEN planned_month = 10 THEN \'OCTOBER\' WHEN planned_month = 11 THEN \'NOVEMBER\' WHEN planned_month = 12 THEN \'DECEMBER\' ELSE NULL END AS planned_month_name, inward_month, CASE WHEN inward_month = 1 THEN \'JANUARY\' WHEN inward_month = 2 THEN \'FEBRUARY\' WHEN inward_month = 3 THEN \'MARCH\' WHEN inward_month = 4 THEN \'APRIL\' WHEN inward_month = 5 THEN \'MAY\' WHEN inward_month = 6 THEN \'JUNE\' WHEN inward_month = 7 THEN \'JULY\' WHEN inward_month = 8 THEN \'AUGUST\' WHEN inward_month = 9 THEN \'SEPTEMBER\' WHEN inward_month = 10 THEN \'OCTOBER\' WHEN inward_month = 11 THEN \'NOVEMBER\' WHEN inward_month = 12 THEN \'DECEMBER\' ELSE NULL END AS inward_month_name, inwarded_qty, status FROM final ORDER BY sku_group, inward_month DESC, planned_month DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            